\item[Q.] 1 Let $\vec{a}, \vec{b}$ be two vectors, and let $P, Q$ and $R$ be the points with position vectors $\vec{a}, \vec{b}$ and $\vec{a}+\vec{b}$, respectively, with respect to the origin $O$. If $|\vec{a}+\vec{b}|=\sqrt{21},|\vec{a}-\vec{b}|=3$, and $\vec{a}$ and $(\vec{a}-\vec{b})$ are perpendicular to each other, then the area of the triangle $O P R$ is

\begin{tabular}[t]{|l|l|l|l|l|l|l|l|}
\hline (A) & $\sqrt{3}$ & (B) & $\frac{\sqrt{3}}{2}$ & (C) & $\frac{3 \sqrt{3}}{2}$ & (D) & $\frac{3}{2}$ \\
\hline
\end{tabular}
\item[Q.] 2 Let $T$ be the tangent to the parabola $y^{2}=16 x$ at the point (64, 32). Let $L$ be the tangent to the same parabola at another point $\left(x_{1}, y_{1}\right)$ on the parabola. If $L$ and $T$ are perpendicular to each other, then the distance between the point $\left(x_{1}, y_{1}\right)$ and the focus of the parabola, is

\begin{tabular}[t]{|l|l|l|l|l|l|l|l|}
\hline (A) & $\frac{15}{4}$ & (B) & 4 & (C) & $\frac{17}{4}$ & (D) & 5 \\
\hline
\end{tabular}
\item[Q.] 3 Let $y:(-\infty, \infty) \rightarrow(0, \infty)$ be the solution of the differential equation
$$\frac{d y}{d x}=\frac{e^{5 x} y^{3}+y^{3}}{e^{x}+e^{x} y^{4}},$$
satisfying $y(0)=\frac{1}{\sqrt{2}}$. Then the value of $y\left(\log _{e} 2\right)$ is

\begin{tabular}[t]{|l|l|l|l|}
\hline (A) & $\sqrt{\frac{5+\sqrt{35}}{2}}$ & (B) & $\sqrt{\frac{7+\sqrt{53}}{2}}$ \\
\hline (C) & $\frac{7+\sqrt{53}}{2}$ & (D) & $\frac{5+\sqrt{35}}{2}$ \\
\hline
\end{tabular}
\end{itemize}
Q. 4 The value of the definite integral
$$\int_{0}^{2} \frac{1}{3^{x}+3} d x$$

\begin{tabular}[t]{|l|l|l|l|l|l|l|l|}
\hline (A) & $\frac{1}{2}$ & (B) & $\frac{1}{3}$ & (C) & $\frac{\log _{\mathrm{e}} 3}{3}$ & (D) & $\frac{\log _{\mathrm{e}} 3}{2}$ \\
